## Text Adventure Game

### World Structure

```xiom
type Room {
  name: Str;
  description: Str;
  exits: Vec[(Str, Int)];
  item_here: Option[Str];
  requires_key: Bool;
}

type World {
  rooms: Vec[Room];
}

fn build_world() -> World {
  let mut rooms: Vec[Room] = Vec[Room].new();

  let room0 = Room{
    name: "Dark Cave",
    description: "A dim cavern. Water drips from the ceiling.",
    exits: Vec[(Str, Int)].new(),
    item_here: Option.Some("Rusty Sword"),
    requires_key: false
  };
  room0.exits.push(("North", 1));
  room0.exits.push(("East", 2));

  rooms.push(room0);
  rooms.push(Room{ name: "Treasure Room", description: "Glittering gold!", exits: Vec[(Str, Int)].new(), item_here: Option.None, requires_key: true });
  rooms.push(Room{ name: "Armory", description: "Weapons on the walls.", exits: Vec[(Str, Int)].new(), item_here: Option.Some("Shield"), requires_key: false });

  World{ rooms: rooms }
}
```

### Player State

```xiom
type Player {
  current_room: Int;
  inventory: Vec[Str];
  has_key: Bool;
  treasures_found: Int;
}
```

### Command Processing

```xiom
fn process_command(cmd: Str, world: &World, player: &mut Player) -> Str {
  if cmd == "look" {
    return look(world, player);
  };
  if cmd == "north" { return move_player(world, player, "North"); };
  if cmd == "south" { return move_player(world, player, "South"); };
  if cmd == "east" { return move_player(world, player, "East"); };
  if cmd == "west" { return move_player(world, player, "West"); };
  if cmd == "take" { return take_item(world, player); };
  if cmd == "inventory" { return show_inventory(player); };
  "I don't understand that."
}
```

### Movement Logic

```xiom
fn move_player(world: &World, player: &mut Player, direction: Str) -> Str {
  let room = world.rooms.get(player.current_room).unwrap();
  let mut i = 0;
  while i < room.exits.len() {
    let (dir, dest) = room.exits.get(i).unwrap();
    if dir == direction {
      let next_room = world.rooms.get(dest).unwrap();
      if next_room.requires_key && !player.has_key {
        return "The door is locked. You need a key.";
      };
      player.current_room = dest;
      return look(world, player);
    };
    i += 1;
  };
  "You can't go that way."
}
```

