use xiom.io;
type Room {
  name: Str;
  north_exit: Int;
  item: Str;
}

type AdventurePlayer {
  room_id: Int;
  has_key: Bool;
}

fn look(rooms: &Vec[Room], player: &AdventurePlayer) -> Str {
  let room = rooms.get(player.room_id).unwrap();
  room.name.clone()
}

fn go_north(rooms: &Vec[Room], player: &mut AdventurePlayer) -> Str {
  let room = rooms.get(player.room_id).unwrap();
  if room.north_exit >= 0 {
    player.room_id = room.north_exit;
    return look(rooms, player);
  };
  "You can't go north."
}

fn main() -> Int {
  let mut rooms: Vec[Room] = Vec[Room].new();
  rooms.push(Room{ name: "Cave", north_exit: 1, item: "" });
  rooms.push(Room{ name: "Hall", north_exit: -1, item: "key" });

  let mut player = AdventurePlayer{ room_id: 0, has_key: false };
  io.println(look(&rooms, &player));
  io.println(go_north(&rooms, &mut player));
  return 0;
}
